def witness_phase_one(prob):
    """Phase-1 LP whose optimal duals form a boxed Farkas witness."""
    n_rows = prob["R"]
    n_coms = prob["K"]
    nlp = prob["n"]
    ntot = nlp + 2 * n_rows + 2 * n_coms
    off_sm = nlp
    off_sp = nlp + n_rows
    off_pp = nlp + 2 * n_rows
    off_pm = nlp + 2 * n_rows + n_coms

    # rows: first R: A v + s+ - s- = b ; then K: E v + p+ - p- = d
    left = sparse.hstack([prob["A_ub"],
                          sparse.identity(n_rows, format="csr") * 1.0,
                          -sparse.identity(n_rows, format="csr"),
                          sparse.csr_matrix((n_rows, 2 * n_coms))],
                         format="csr")
    if n_coms:
        right = sparse.hstack([
            prob["A_eq"],
            sparse.csr_matrix((n_coms, 2 * n_rows)),
            sparse.identity(n_coms, format="csr"),
            -sparse.identity(n_coms, format="csr")], format="csr")
    else:
        right = sparse.csr_matrix((0, ntot))
    g_eq = sparse.vstack([left, right], format="csr")
    h_eq = np.concatenate([prob["b_ub"], prob["b_eq"]
                           if prob["b_eq"] is not None
                           else np.zeros(0)])

    cvec = np.zeros(ntot, dtype=np.float64)
    # cost lives on the "violation" slacks: s- (allows A v > b) and p+/p-
    cvec[off_sp:off_sp + n_rows] = 1.0
    if n_coms:
        cvec[off_pp:off_pp + n_coms] = 1.0
        cvec[off_pm:off_pm + n_coms] = 1.0

    for opts in _witness_lp_options():
        res = _safe_linprog(cvec, None, None, g_eq, h_eq,
                            [(0.0, None)] * ntot, "highs", opts)
        if res is None or res.status != 0 or res.eqlin is None:
            continue
        marg = res.eqlin.marginals
        if marg is None or len(marg) != n_rows + n_coms:
            continue
        y = np.array(marg[:n_rows], dtype=np.float64)
        q = np.array(marg[n_rows:], dtype=np.float64)
        obj = float(res.fun)
        if not np.isfinite(obj) or abs(obj) < 1e-12:
            continue
        if obj > 0:
            y = y / obj
            q = q / obj
            return _finish_witness(prob, y, q)
    return None


def _finish_witness(prob, y, q):
    if not (np.all(np.isfinite(y)) and np.all(np.isfinite(q))):
        return None
    if np.max(np.abs(y), initial=0.0) > 1e8 or np.max(np.abs(q), initial=0.0) > 1e8:
        return None
    y = np.minimum(y, 0.0)
    nv, _ = norm_violation(prob, y, q)
    dv = dual_violation_inf(prob, y, q)
    tier = _tier_from_worst(max(nv, dv))
    return {"tier": tier, "y": y, "q": q}


def dual_violation_inf(prob, y, q):
    """Worst violation of A^T y + E^T q <= 0 (Farkas conditions)."""
    if prob["R"] == 0:
        return 0.0
    col = prob["A_ub"].T @ y
    if prob["A_eq"] is not None:
        col = col + prob["A_eq"].T @ q
    if col.size == 0:
        return 0.0
    return max(0.0, float(col.max()) / 1e-7)


# --------------------------------------------------------------------------
# LP driver
# --------------------------------------------------------------------------

def _safe_linprog(c, a_ub, b_ub, a_eq, b_eq, bounds, method, options):
    opts = dict(options)
    opts.setdefault("primal_feasibility_tolerance", 1e-9)
    opts.setdefault("dual_feasibility_tolerance", 1e-9)
    limit = _remaining_time() - 1.0
    if limit < 1.0:
        return None
    opts.setdefault("time_limit", min(20.0, limit))
    try:
        return linprog(c, A_ub=a_ub, b_ub=b_ub, A_eq=a_eq, b_eq=b_eq,
                       bounds=bounds, method=method, options=opts)
    except Exception:
        return None


# Simplex variants only: the interior point solver can behave pathologically
# on some degenerate models, and simplex has been sufficient in all tests.
OPTIMAL_STRATEGIES = (
    ("highs", {"presolve": True}),
    ("highs-ds", {"presolve": True}),
    ("highs", {"presolve": False}),
    ("highs-ds", {"presolve": False}),
)

REQUEST_TIME_LIMIT = 60.0
PROCESS_TIME_LIMIT = 780.0   # stay well inside the 900s process budget

_STATE = {"start": None, "deadline": None}


def _reset_deadline():
    now = time.monotonic()
    if _STATE["start"] is None:
        _STATE["start"] = now
    remaining_process = PROCESS_TIME_LIMIT - (now - _STATE["start"])
    if remaining_process < 5.0:
        _STATE["deadline"] = now + 5.0
    else:
        _STATE["deadline"] = now + min(REQUEST_TIME_LIMIT, remaining_process)


def _remaining_time():
    dl = _STATE["deadline"]
    if dl is None:
        return REQUEST_TIME_LIMIT
    return dl - time.monotonic()



def infeasible_response(req, cert):
    return {
        "epoch": req["epoch"],
        "status": "infeasible",
        "certificate": {
            "inequality": [_san(v) for v in cert["y"].tolist()],
            "equality": [_san(v) for v in cert["q"].tolist()],
        },
    }


def solve_request(req):
    prob = build_problem(req)
    prob["epoch"] = req["epoch"]
    _reset_deadline()
    deadline = _STATE["deadline"]

    best_opt = None
    best_inf = None

    def consider(cand):
        nonlocal best_opt
        if cand is None:
            return False
        if cand["tier"] >= 2:
            return True
        if best_opt is None or cand["tier"] > best_opt["tier"]:
            best_opt = cand
        return False

    def try_optimal(res):
        """Grade an optimal solver result with the available duals."""
        primal = make_primal(prob, res)
        if primal is None:
            return None
        dual = dual_from_marginals(prob, res)
        if dual is not None:
            cand = optimal_response(prob, primal, dual)
            if cand["tier"] >= 1:
                return cand
            # keep the best so far even if only marginal
            consider(cand)
        dual = dual_by_lp(prob)
        if dual is not None:
            cand = optimal_response(prob, primal, dual)
        else:
            cand = None
        return cand

    infeasible = False
    stop = len(OPTIMAL_STRATEGIES)
    for idx, (method, opts) in enumerate(OPTIMAL_STRATEGIES):
        if time.monotonic() > deadline:
            break
        res = _safe_linprog(prob["c"], prob["A_ub"], prob["b_ub"],
                            prob["A_eq"], prob["b_eq"], (0.0, None),
                            method, opts)
        if res is None:
            continue
        if res.status == 0:
            cand = try_optimal(res)
            if cand is not None and consider(cand):
                return cand["response"]
        elif res.status == 2:
            infeasible = True
            stop = idx + 1
            break
        # status 1/3/4: try the next strategy

    if infeasible:
        for gen in (witness_min_rho, witness_phase_one):
            if time.monotonic() > deadline:
                break
            try:
                cert = gen(prob)
            except Exception:
                cert = None
            if cert is None:
                continue
            if cert["tier"] >= 2:
                return infeasible_response(req, cert)
            if best_inf is None or cert["tier"] > best_inf["tier"]:
                best_inf = cert
        if best_inf is not None and best_inf["tier"] >= 1:
            return infeasible_response(req, best_inf)
        # Witness generation failed: the infeasibility verdict may be wrong,
        # so probe the remaining strategies for a primal solution.
        for method, opts in OPTIMAL_STRATEGIES[stop:]:
            if time.monotonic() > deadline:
                break
            res = _safe_linprog(prob["c"], prob["A_ub"], prob["b_ub"],
                                prob["A_eq"], prob["b_eq"], (0.0, None),
                                method, opts)
            if res is not None and res.status == 0:
                cand = try_optimal(res)
                if cand is not None and consider(cand):
                    return cand["response"]

    if best_opt is not None and best_opt["tier"] >= 1:
        return best_opt["response"]
    if best_inf is not None:
        return infeasible_response(req, best_inf)
    if best_opt is not None:
        return best_opt["response"]
    # Nothing worked at all; report infeasible with an empty witness rather
    # than crashing the process.
    return {
        "epoch": req["epoch"],
        "status": "infeasible",
        "certificate": {
            "inequality": [0.0] * prob["R"],
            "equality": [0.0] * prob["K"],
        },
    }


# --------------------------------------------------------------------------
# Line oriented IO
# --------------------------------------------------------------------------

def iter_lines(stream):
    """Yield each line (newline stripped); yields None for overlong lines.

    Reads use a single raw read per call (never blocking to fill a buffer),
    so the controller can send one line and wait for its response.
    """
    reader = stream.read1 if hasattr(stream, "read1") else stream.read
    buf = bytearray()
    pending = False
    overlong = False
    while True:
        chunk = reader(65536)
        if not chunk:
            break
        pos = 0
        n = len(chunk)
        while pos < n:
            i = chunk.find(b"\n", pos)
            if i < 0:
                buf.extend(chunk[pos:])
                if len(buf) > MAX_LINE:
                    # do not retain an overlong line in memory
                    overlong = True
                    del buf[:]
                pending = True
                pos = n
                break
            buf.extend(chunk[pos:i + 1])
            pending = True
            pos = i + 1
            if overlong or len(buf) > MAX_LINE:
                yield None
            else:
                yield bytes(buf[:-1])
            del buf[:]
            pending = False
            overlong = False
    if pending:
        if overlong:
            yield None
        else:
            yield bytes(buf)


def sanitize(obj):
    """Ensure every emitted numeric value is a finite JSON number."""
    if isinstance(obj, dict):
        return {k: sanitize(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [sanitize(v) for v in obj]
    if isinstance(obj, float):
        if not np.isfinite(obj):
            return 0.0
        return obj
    if isinstance(obj, np.floating) or isinstance(obj, np.integer):
        v = obj.item()
        if isinstance(v, float) and not np.isfinite(v):
            return 0.0
        return v
    return obj


def emit(obj):
    sys.stdout.write(json.dumps(sanitize(obj)))
    sys.stdout.write("\n")
    sys.stdout.flush()


def main():
    for line in iter_lines(sys.stdin.buffer):
        if line is None:
            emit({"status": "invalid"})
            continue
        try:
            text = line.decode("utf-8")
        except UnicodeDecodeError:
            emit({"status": "invalid"})
            continue
        try:
            req = validate(parse_request(text))
        except Invalid:
            emit({"status": "invalid"})
            continue
        except Exception:
            emit({"status": "invalid"})
            continue
        try:
            resp = solve_request(req)
        except Exception as exc:  # pragma: no cover - defensive
            sys.stderr.write("solver failure: %r\n" % (exc,))
            resp = {"status": "invalid"}
        emit(resp)


if __name__ == "__main__":
    main()
